import java.util.*;
class LRUCache {
    private final int cap;
    private final Map<Integer, Node> map = new HashMap<>();
    private final Node head = new Node(), tail = new Node();
    LRUCache(int cap) {
        this.cap = cap; head.next = tail; tail.prev = head;
    }
    public int get(int key) {
        if (!map.containsKey(key)) return -1;
        Node n = map.get(key); remove(n); addFront(n); return n.val;
    }
    public void put(int key, int val) {
        if (map.containsKey(key)) remove(map.get(key));
        if (map.size() == cap) { map.remove(tail.prev.key); remove(tail.prev); }
        addFront(new Node(key, val));
    }
    void remove(Node n) { map.remove(n.key); n.prev.next=n.next; n.next.prev=n.prev; }
    void addFront(Node n) { map.put(n.key,n); n.next=head.next; n.prev=head; head.next.prev=n; head.next=n; }
    static class Node { int key,val; Node prev,next; Node(){} Node(int k,int v){key=k;val=v;} }
}

